package kr.blinklabs.blinklink.tests;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.os.*;import org.json.*;import kr.blinklabs.blinklink.*;
public final class MacroInstrumentation extends Instrumentation {
 int count;Context c;void ok(boolean yes,String name){if(!yes)throw new AssertionError(name);count++;Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}
 void nap(long ms){SystemClock.sleep(ms);}String log(){return MacroStore.prefs(c).getString("log","");}
 JSONObject macro(String name,int trigger,int action,String value)throws Exception{return MacroStore.fresh().put("name",name).put("enabled",true).put("trigger",trigger).put("actions",new JSONArray().put(new JSONObject().put("type",action).put("value",value)));}
 void command(String action,String id)throws Exception{runOnMainSync(()->MacroService.send(c,action,id));nap(500);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){c=getTargetContext();SharedPreferences p=MacroStore.prefs(c);String backup=p.getString("definitions","[]"),oldLog=p.getString("log","");int volume=c.getSystemService(AudioManager.class).getStreamVolume(AudioManager.STREAM_MUSIC);Bundle result=new Bundle();Activity activity=null;int code=Activity.RESULT_CANCELED;
 try{if(!android.os.Build.HARDWARE.matches("ranchu|goldfish"))throw new AssertionError("emulator required");ok(!MacroService.running,"isolated service precondition");p.edit().putString("definitions","[]").putString("log","").commit();activity=startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
 JSONObject m=macro("sequence",0,0,"sequence start");m.getJSONArray("actions").put(new JSONObject().put("type",2).put("value","1")).put(new JSONObject().put("type",4).put("value","0"));MacroStore.save(c,m);ok(MacroStore.all(c).length()==1,"definition persisted");
 String exported=MacroStore.exportData(c);ok(MacroStore.importData(c,exported)==1,"export import roundtrip");JSONObject clone=MacroStore.all(c).getJSONObject(1);ok(!clone.getBoolean("enabled")&&!clone.getString("id").equals(m.getString("id")),"import disabled with fresh identity");
 int before=MacroStore.all(c).length();try{MacroStore.importData(c,"{\"version\":1,\"macros\":["+m.toString()+",{}]}");throw new AssertionError("invalid import accepted");}catch(JSONException expected){}ok(MacroStore.all(c).length()==before,"invalid import atomic rollback");
 for(String value:new String[]{"-1","101","x"}){JSONObject bad=macro("bad",0,4,value);try{MacroStore.validate(bad);throw new AssertionError("invalid range accepted");}catch(JSONException expected){ok(true,"volume rejects "+value);}}
 JSONObject bad=macro("bad time",1,0,"test").put("time","25:00");try{MacroStore.validate(bad);throw new AssertionError("invalid time");}catch(JSONException expected){ok(true,"invalid schedule rejected");}
 command("run",m.getString("id"));nap(1800);ok(log().contains("sequence · 완료"),"notification wait volume sequence completed");ok(c.getSystemService(AudioManager.class).getStreamVolume(AudioManager.STREAM_MUSIC)==0,"actual media volume changed");
 JSONObject blocked=macro("blocked",0,0,"should not run").put("wifi","__not_this_network__");MacroStore.save(c,blocked);command("run",blocked.getString("id"));ok(log().contains("blocked · 추가 조건 불일치")&&!log().contains("blocked · 완료"),"conditions gate manual execution");
 JSONObject fail=macro("fail",0,3,"invalid.missing.package");fail.getJSONArray("actions").put(new JSONObject().put("type",0).put("value","must not run"));MacroStore.save(c,fail);command("run",fail.getString("id"));nap(500);ok(log().contains("fail · 실패")&&!log().contains("fail · 완료"),"failed action stops remaining chain");
 JSONObject slow=macro("cancel",0,2,"5");slow.getJSONArray("actions").put(new JSONObject().put("type",4).put("value","100"));MacroStore.save(c,slow);command("run",slow.getString("id"));runOnMainSync(()->c.stopService(new Intent(c,MacroService.class)));nap(5500);ok(log().contains("cancel · 중지됨")&&c.getSystemService(AudioManager.class).getStreamVolume(AudioManager.STREAM_MUSIC)==0,"stop cancels delayed actions");
 JSONObject scheduled=macro("schedule",1,0,"scheduled notification").put("time",new java.text.SimpleDateFormat("HH:mm",java.util.Locale.US).format(new java.util.Date()));MacroStore.save(c,scheduled);command("monitor",null);nap(1000);ok(log().contains("schedule · 완료"),"current minute schedule fires");String old=log();command("monitor",null);nap(500);int occurrences=log().split("schedule · 시작",-1).length-1;ok(occurrences==1,"schedule deduplicated across monitor restart");
 JSONObject connect=macro("charge",2,0,"charging");MacroStore.save(c,connect);JSONObject disconnect=macro("unplug",3,0,"unplugged");MacroStore.save(c,disconnect);
 getUiAutomation().executeShellCommand("dumpsys battery unplug").close();nap(16500);ok(log().contains("unplug · 완료"),"charging disconnect edge");
 getUiAutomation().executeShellCommand("dumpsys battery set usb 1").close();nap(16500);ok(log().contains("charge · 완료"),"charging connect edge");
 JSONObject screen=macro("screen",5,0,"screen on");MacroStore.save(c,screen);getUiAutomation().executeShellCommand("input keyevent 223").close();nap(500);getUiAutomation().executeShellCommand("input keyevent 224").close();nap(1000);ok(log().contains("screen · 완료"),"screen receiver executes enabled macro");
 runOnMainSync(()->c.stopService(new Intent(c,MacroService.class)));nap(500);ok(!MacroService.running,"explicit monitoring stop");MacroStore.remove(c,m.getString("id"));ok(MacroStore.find(c,m.getString("id"))==null,"delete definition");result.putString("stream","PASS "+count+" instrumentation assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL "+e.toString()+"\n"+android.util.Log.getStackTraceString(e));code=Activity.RESULT_CANCELED;}
 finally{try{getUiAutomation().executeShellCommand("dumpsys battery reset").close();}catch(Exception ignored){}c.stopService(new Intent(c,MacroService.class));nap(300);p.edit().putString("definitions",backup).putString("log",oldLog).commit();c.getSystemService(AudioManager.class).setStreamVolume(AudioManager.STREAM_MUSIC,volume,0);if(activity!=null)activity.finish();}
 finish(code,result);
 }
}
